const e={model:"gemma4:12b",digest:"4eb23ef187e2c5462566d6a1d3bbbc2f1346d0b4327cbb66d58fffbcc9b2b05c",promptVersion:3,date:"2026-08-30",status:{"fi.character.awareness.why":"reviewed","fi.character.control.why":"reviewed","fi.character.endurance.why":"reviewed","fi.character.precision.why":"reviewed","fi.character.speed.why":"reviewed","fi.energy.recovery.auxiliary":"reviewed","fi.energy.recovery.dominant":"reviewed","fi.energy.recovery.inferior":"reviewed","fi.energy.recovery.shadow":"reviewed","fi.energy.recovery.tertiary":"reviewed","fi.feeder.ne":"reviewed","fi.feeder.ni":"reviewed","fi.feeder.se":"reviewed","fi.feeder.si":"reviewed","fi.feeder.te":"reviewed","fi.fieldNotes.mirror":"reviewed","fi.fieldNotes.vignette.accusation":"reviewed","fi.fieldNotes.vignette.grip":"reviewed","fi.fieldNotes.vignette.lockedDrawer":"reviewed","fi.fieldNotes.vignette.loop":"reviewed","fi.fieldNotes.vignette.mediation":"reviewed","fi.fieldNotes.vignette.mistakenForNoOpinion":"reviewed","fi.fieldNotes.vignette.silentCompass":"reviewed","fi.hero.heading":"reviewed","fi.hero.subtitle":"reviewed","fi.hero.tag":"reviewed","fi.lab.btn.authBad.label":"reviewed","fi.lab.btn.authBad.sub":"reviewed","fi.lab.btn.authGood.label":"reviewed","fi.lab.btn.authGood.sub":"reviewed","fi.lab.btn.fakeBad.label":"reviewed","fi.lab.btn.fakeBad.sub":"reviewed","fi.lab.btn.fakeGood.label":"reviewed","fi.lab.btn.fakeGood.sub":"reviewed","fi.lab.meter.pleasure":"reviewed","fi.lab.meter.stress":"reviewed","fi.lab.narration.authBad":"reviewed","fi.lab.narration.authGood":"reviewed","fi.lab.narration.fakeBad":"reviewed","fi.lab.narration.fakeBadEnd":"reviewed","fi.lab.narration.fakeBadMid":"reviewed","fi.lab.narration.fakeGood":"reviewed","fi.lab.narration.fakeGoodEnd":"reviewed","fi.lab.narration.intro":"reviewed","fi.meta.title":"reviewed","fi.slot.auxiliary":"reviewed","fi.slot.critical":"reviewed","fi.slot.demon":"reviewed","fi.slot.dominant":"reviewed","fi.slot.inferior":"reviewed","fi.slot.opposing":"reviewed","fi.slot.tertiary":"reviewed","fi.slot.trickster":"reviewed","fi.zoneA.canvasAria":"reviewed","fi.zoneB.heading":"reviewed","fi.zoneB.lede":"reviewed","fi.zoneB.railAria":"reviewed","fi.zoneC.heading":"reviewed","fi.zoneC.lede":"reviewed","fi.zoneD.canvasAria":"reviewed","fi.zoneD.heading":"reviewed","fi.zoneD.kicker":"reviewed","fi.zoneD.lede":"reviewed","fi.zoneE.lede":"reviewed"}},a={_meta:e,"fi.character.awareness.why":"el asiento más transparente en la pila: el tono es siempre audible","fi.character.control.why":"dirigible hasta la línea que un valor traza; inamovible más allá de ella","fi.character.endurance.why":"la convicción es natural y constante: mantener el estándar no tiene coste","fi.character.precision.why":"la jerarquía de lo que importa es profunda, tranquila y exacta","fi.character.speed.why":"profundo y tranquilo — el veredicto es total y rara vez rápido","fi.energy.recovery.auxiliary":"Recuperación rápida y limpia.","fi.energy.recovery.dominant":"Se recarga en minutos — y parcialmente durante el uso (flujo).","fi.energy.recovery.inferior":"La repisa de la resaca: ~30 min en los que todo el sistema funciona con poca intensidad.","fi.energy.recovery.shadow":"Incompleto — parte de la carga simplemente no regresa hoy.","fi.energy.recovery.tertiary":"Una recarga más lenta; el descanso debe ser deliberado.","fi.feeder.ne":{figure:"La nebulosa se expande ampliamente, con la bruma derivando en penachos ramificados.",mechanism:"Ne — intuición extravertida, la auxiliar aquí — ofrece posibilidades ramificadas, y cada una se coteja con el estándar interno: ¿podría vivir con esto? ¿quién sería yo en ese mundo? Muchos futuros se sostienen ligeramente a la vez, esperando ver cuál resulta auténtico.",pair:"el acoplamiento INFP",provenance:"myers"},"fi.feeder.ni":{figure:"Larga quietud, y de repente, toda la nebulosa cambia de color a la vez.",mechanism:"Ni — intuición introvertida — envía pocas experiencias, cada una ya condensada en un único significado. Fi tiene poco que sopesar y mucho que absorber, reordenando lo que le importa ante cada llegada. Ninguna pila estándar sitúa Ni directamente sobre Fi; este acoplamiento es el propio experimento de pensamiento del sitio.",pair:"un acoplamiento no estándar",provenance:"currents"},"fi.feeder.se":{figure:"La nebulosa se dibuja apretada y saturada, densa alrededor de lo que está presente.",mechanism:"Se — sensación extravertida — entrega el presente vívido y concreto, y Fi sopesa lo que está realmente aquí frente a ello. El juicio reside en las manos y los ojos: sabor, belleza y la acción correcta sentida directamente en lugar de argumentada.",pair:"la combinación ISFP",provenance:"myers"},"fi.feeder.si":{figure:"La niebla rodea el núcleo en anillos cerrados: nada entra, nada sale.",mechanism:"Si — sensación introvertida, la función terciaria del INFP — reproduce la experiencia almacenada en lugar de recopilar nueva. Las viejas heridas y viejas bondades se vuelven a sentir bajo el mismo estándar, los veredictos se renuevan en lugar de reevaluarse. Este es el bucle, visto desde dentro.",pair:"el acoplamiento de bucle (Fi–Si, INFP bajo estrés)",provenance:"community"},"fi.feeder.te":{figure:"El emisor brilla, pero la niebla no tiene nada alrededor para rodear.",mechanism:"Te — pensamiento extravertido — es una función de juicio, por lo que entrega veredictos sobre la eficiencia en lugar de la experiencia vivida. Fi recibe casi nada que pueda sopesar y permanece inactiva por hambre. Las pilas reales alternan el juicio con la percepción precisamente para que algo esté siempre reuniendo material.",pair:"Juicio alimentando a juicio",provenance:"myers"},"fi.fieldNotes.mirror":{figure:"Mismo elemento, actitudes opuestas: un instrumento afinado para la sala, otro para su propia nota.",mechanismHtml:"Donde <strong>Fe</strong> lee el tono emocional de la sala y construye armonía social, <strong>Fi</strong> lee el tono emocional del yo y construye integridad personal. Fe intercambia la preferencia individual por la unidad del grupo; Fi intercambia la aprobación del grupo por la verdad interna.",provenance:"jung"},"fi.fieldNotes.vignette.accusation":{figure:"Negarse a teñir la niebla para que coincida con la habitación.",kind:"la acusación",mechanism:"La acusación llega tarde o temprano, normalmente a mitad de la negociación, usualmente de alguien fluido en Fe. Lo que ocurre realmente: Fi no falsificará el acuerdo, y en una sala que se basa en el acuerdo visible, negarse a fingirlo se interpreta como deserción. La negativa no es descuido — un sí sin falsificar es lo único que Fi considera que vale la pena ofrecer a alguien, y tiene el precio correspondiente.",provenance:"community",title:"Egoísta"},"fi.fieldNotes.vignette.grip":{figure:"Un núcleo tenue que brilla de repente.",kind:"la garra",mechanism:"Un ESTJ bajo estrés prolongado cae en una moralización abrumadora y herida — acusaciones de traición y falta de corazón entregadas con una intensidad que sobresalta a todos. Esta es la garra: una dominante agotada que cede el control a la inferior Fi, que estalla sin ninguna de las proporciones de una Fi practicada.",provenance:"quenk",title:"La erupción inferior"},"fi.fieldNotes.vignette.lockedDrawer":{figure:"Una pequeña nebulosa detrás de un cristal esmerilado.",kind:"como terciaria",mechanism:'Fi terciaria en un ISTJ es un registro moral privado bajo un exterior procedimental: el cliente que no aceptarán, la broma que termina una amistad, la donación que nadie escucha — compromisos mantenidos durante décadas y explicados, si se les presiona, como "así es como hago las cosas". Los valores son reales; el vocabulario para ellos nunca se construyó.',provenance:"grant",title:"El cajón cerrado"},"fi.fieldNotes.vignette.loop":{figure:"La bruma gira en anillos cerrados: tierna, sin aire, sellada.",kind:"el bucle",mechanism:"Bajo estrés, la Fi dominante de un INFP se une con la Si terciaria y reproduce viejas heridas y viejas bondades frente al mismo estándar interno: los veredictos se vuelven a sentir en lugar de volver a probarse. Ambas funciones miran hacia adentro, por lo que nada en la pareja puede interrumpirlo: el patrón que los foros de tipología llaman un bucle.",provenance:"community",title:"El bucle"},"fi.fieldNotes.vignette.mediation":{figure:"Una función central no puede promediar otras dos.",kind:"el instrumento incorrecto",mechanism:"Pida a Fi que presida un compromiso entre dos partes que considera ambas parcialmente erróneas, y la herramienta se atasca. Evalúa todo según un estándar interno y no tiene una operación nativa para dividir las diferencias entre los demás. Puede hacer el trabajo —por principio, con coste— mientras la mesa confunde su silencio con asentimiento y sus veredictos con terquedad. Este es el terreno de Fe; Fi visita en placas extranjeras.",provenance:"community",title:"La Mediación"},"fi.fieldNotes.vignette.mistakenForNoOpinion":{figure:"Niebla tranquila, núcleo fijo.",kind:"malinterpretado",mechanism:"Semanas de flexibilidad amable sobre restaurantes, planes y procesos — luego se cruza una línea y llega un veredicto completo, final y no negociable. La señal que diferencia esto de la mera amabilidad: la posición se decidió mucho antes de la reunión, en privado. Fe negocia su postura en la sala; la postura de Fi precede a la sala, y la sala es simplemente la última en enterarse.",provenance:"community",title:"Confundido con falta de opinión"},"fi.fieldNotes.vignette.silentCompass":{figure:"El núcleo no discute; simplemente mantiene su color.",kind:"avistamiento de campo",mechanism:"Un INFP se sienta en silencio en una reunión donde todos aceptan un compromiso. Entonces dicen que no —no fuerte, ni con un argumento de diez puntos, sino con una firmeza que detiene la sala. La posición se decidió mucho antes de que alguien hablara; la reunión acaba de enterarse.",provenance:"community",title:"La brújula silenciosa"},"fi.hero.heading":"La arquitectura de {fn}","fi.hero.subtitle":"Una nebulosa silenciosa alrededor de un tono central — sopesando cada experiencia frente a una brújula interna indiscutible.","fi.hero.tag":"sentimiento introvertido","fi.lab.btn.authBad.label":"Vive un duelo auténtico","fi.lab.btn.authBad.sub":"verdadero, doloroso, profundamente arraigado","fi.lab.btn.authGood.label":"Experimenta una alegría auténtica","fi.lab.btn.authGood.sub":"algo verdadero y resonante","fi.lab.btn.fakeBad.label":"Presenciar una violación inauténtica","fi.lab.btn.fakeBad.sub":"una falsedad desgarra la bruma","fi.lab.btn.fakeGood.label":"Oye un cumplido inauténtico","fi.lab.btn.fakeGood.sub":"la adulación no cala","fi.lab.meter.pleasure":"Placer de la resonancia","fi.lab.meter.stress":"Estrés del sistema","fi.lab.narration.authBad":{figure:"La niebla se ralentiza, se oscurece y lo retiene, en lo profundo de la nebulosa.",mechanism:"Algo doloroso — y verdadero. Fi no lo desvía: el duelo se absorbe y se mantiene, porque para esta función la rectitud supera al confort. El estrés aumenta, y también la sensación de estar intacto — esto, también, dará forma al estándar.",provenance:"currents"},"fi.lab.narration.authGood":{figure:"Resuena contra el núcleo y se difunde en lo profundo — la bruma gira suavemente, y toda la nebulosa se calienta hacia lo que fue asimilado.",mechanism:"Algo alegre —y verdadero— llega. Fi lo asimila por completo: la experiencia se absorbe en lugar de solo notarse, y recolorea un poco el estándar. Lo que se ama genuinamente se convierte en parte de cómo se pondera todo lo demás.",provenance:"currents"},"fi.lab.narration.fakeBad":{figure:"Rasga la nebulosa directamente — la bruma se aparta de su trayectoria, con un vacío arrastrándose tras ella —",mechanism:"Una falsedad golpea algo que importa. Este es el único evento que Fi no puede archivar silenciosamente: una violación de los estándares exige una respuesta de todo el sistema.",provenance:"currents"},"fi.lab.narration.fakeBadEnd":{figure:"...la niebla se detiene y el color se estabiliza.",mechanism:"La herida se cierra y el estándar ha cambiado de forma — más oscuro en algunos puntos, reordenado en otros. Fi conserva lo que fue real y recuerda dónde sangró.",provenance:"currents"},"fi.lab.narration.fakeBadMid":{figure:"— parte de la bruma se filtra a través de la herida y todo el campo se desplaza hacia el rojo.",mechanism:"Mantener la violación tiene un coste de sustancia real: todo lo unido al valor herido tiene que encontrar un nuevo lugar a su alrededor.",provenance:"currents"},"fi.lab.narration.fakeGood":{figure:"La niebla se niega a mezclarse con ella...",mechanism:"La adulación llega —agradable, brillante y hueca. Falla la prueba de autenticidad al contacto, así que no hay nada que absorber: Fi no puede ser pagada en moneda falsa.",provenance:"currents"},"fi.lab.narration.fakeGoodEnd":{figure:"...se desliza por las paredes interiores, sin disolver nada, y sale exactamente como entró.",mechanism:"La cortesía se tolera educadamente y se libera sin cambios. No se guardó nada; no era necesario. Lo que nunca fue real nunca estuvo realmente en la sala.",provenance:"currents"},"fi.lab.narration.intro":"Haz clic en un botón para enviarle una experiencia a Fi y observa cómo la absorbe, retiene, rechaza o deja que se filtre en torno a lo que llega.","fi.meta.title":"Fi — Sentimiento Introvertido · CURRENTS","fi.slot.auxiliary":{example:"Un ENFP persigue un nuevo proyecto durante quince días y luego lo abandona en una tarde cuando esto significaría halagar a alguien a quien desprecia.",figure:"La nebulosa se vuelve más pequeña y brilla más cuando se solicita una comprobación.",mechanism:"En el segundo asiento, Fi se consulta en lugar de ejecutarse continuamente: valida lo que la función de percepción dominante aporta — ¿es esto nosotros? ¿podría vivir con esto? — silenciosamente en segundo plano, y decisivamente en los momentos exactos que importan. Entre veredictos, se mantiene al margen.",provenance:"myers"},"fi.slot.critical":{example:"Un ISFJ pasa una hora sin dormir cuestionándose si su duelo es realmente por la pérdida o por ellos mismos.",figure:"Remolinos fríos cruzan la nebulosa, raleando la bruma por donde pasan.",mechanism:"En el sexto asiento, Fi se vuelve hacia adentro como un interrogador del corazón: ¿sabes siquiera lo que quieres? ¿no son estos sentimientos autocomplacientes? Las auditorías son esporádicas y duras, dirigidas principalmente hacia el yo, y mejores cuestionando un valor que construyendo uno.",provenance:"beebe"},"fi.slot.demon":{example:"A las 3 a.m., un INTP está repentinamente, sin palabras, seguro de que todo aquel que alguna vez le quiso estaba equivocado.",figure:"El núcleo se invierte: una estrella oscura que atrae la bruma en lugar de iluminarla.",mechanism:"El octavo asiento es el más raro y peor. Cuando hay una erupción —normalmente al final de una larga mala racha— produce una certeza moral total dirigida hacia el interior: una convicción de falta de valor o traición que se presenta como un hecho evidente. Es el asiento menos practicado en la pila, no un veredicto.",provenance:"beebe"},"fi.slot.dominant":{example:'Al preguntarle por qué rechazaron la oferta, un INFP dice "no era correcto" — y es correcto, y no puede decir nada más durante una semana.',figure:"CURRENTS representa esto como una nebulosa en pleno resplandor: un núcleo estable, con la bruma girando con calma a su alrededor.",mechanism:"En el primer asiento, Fi evalúa todo frente a un estándar interno sentido de lo que importa, y la evaluación se ejecuta continuamente con casi ningún coste. Los veredictos llegan sin argumentos adjuntos: el saber viene primero, la explicación después, si es que hay alguna. El precio es la portabilidad: el estándar es preciso pero difícil de mostrar a otros.",provenance:"myers"},"fi.slot.inferior":{example:"Un ENTJ en plena crisis anuncia, ante una reunión atónita, que nadie aquí les ha valorado jamás.",figure:"Una nebulosa tenue con un núcleo parpadeante — un largo silencio, y luego un clima repentino.",mechanism:"En el cuarto asiento, Fi tiene el coste más alto por uso y se usa menos. En el día a día, los sentimientos se tratan como ruido en los datos; bajo estrés prolongado, el asiento puede tomar el control y producir un sentimiento herido y moralista que no suena como ellos — la erupción que Quenk llama la garra.",provenance:"quenk"},"fi.slot.opposing":{example:"Un ESFJ que ha absorbido quejas durante toda la tarde rechaza de repente una, por principio, y no se dejará mover.",figure:"Bajo la línea de flotación del raíl, la nebulosa se endurece, con la bruma erizada en lugar de girar.",mechanism:'El quinto asiento abre la sombra — las cuatro posiciones que una persona rara vez ejecuta, y mayormente sin notarlo. Aquí Fi despierta en contra: cuando la armonización habitual de Fe de la persona es desafiada, surge una postura personal — "no me importa lo que necesite la sala, aquí es donde estoy" — protectora, punzante y brevemente inamovible.',provenance:"beebe"},"fi.slot.tertiary":{example:"Un ISTJ ha financiado discretamente una causa durante veinte años y la llama «simplemente una orden permanente».",figure:"Una pequeña nebulosa, densa en el centro, casi opaca desde el exterior.",mechanism:"En el asiento terciario, Fi es real pero estrecho y mayormente privado: lealtad feroz a unas pocas personas y principios, rara vez explicada y a menudo disfrazada de practicidad. Se fortalece con la edad, y bajo estrés puede emparejarse con la función dominante en un circuito cerrado que ninguna visión externa corrige: el patrón llamado bucle.",provenance:"grant"},"fi.slot.trickster":{example:"Cuando se les pregunta qué es lo que realmente quieren, un ENTP construye tres argumentos divertidos para tres respuestas incompatibles y no elige ninguna.",figure:"La nebulosa se niega a fijarse en un color: refleja aquello que se dirige hacia ella.",mechanism:"En el séptimo asiento, que se le pregunte qué siente realmente se registra como una trampa. La persona desvía con encanto o juego contrariante, y genuinamente no puede distinguir un valor de una preferencia desde el interior —la ceguera es real, no estratégica, y no hay malicia en ella.",provenance:"beebe"},"fi.zoneA.canvasAria":"Representación visual interactiva de Feeling Introvertido como una nebulosa luminosa","fi.zoneB.heading":"Las ocho caras de Fi","fi.zoneB.lede":"El lienzo representa Fi como una nebulosa alrededor de un núcleo: cada experiencia que entra se sopesa frente a un tono interior. El lugar donde Fi se sitúa en la pila de una persona —el orden fijo en el que aparecen sus ocho funciones— cambia la forma en que se realiza ese pesaje. Haz clic en una posición para ver el cambio y arrastra el deslizador de madurez para ver cómo los asientos inferiores ganan fidelidad con la edad.","fi.zoneB.railAria":"Posiciones de la pila para Fi","fi.zoneC.heading":"¿Qué alimenta a Fi?","fi.zoneC.lede":"Fi juzga; no recopila. Una función de percepción —su alimentadora— tiene que entregar las experiencias que pesa, y cuál es la que entrega cambia lo que el pesaje construye. Haz clic en una alimentadora para ver cómo la nebulosa cambia de forma y movimiento.","fi.zoneD.canvasAria":"Escenario de simulación del laboratorio de verificación","fi.zoneD.heading":"Laboratorio de Verificación","fi.zoneD.kicker":"Zona D · laboratorio de verificación","fi.zoneD.lede":"Observa cómo Fi sopesa las experiencias frente a su único estándar interno en tiempo real. Cada botón envía un tipo diferente de evento — alegría verdadera, duelo real, adulación, una violación — y los medidores rastrean cuál es el coste de cada uno.","fi.zoneE.lede":"Patrones de la naturaleza: cómo Fi se manifiesta en la vida diaria."};export{e as _meta,a as default};
